python3 -c "
import re,os
root=open('AlgebraicJacobian.lean').read()
imports=set(re.findall(r'^import\s+(\S+)',root,re.M))
# transitive
def mod2path(m): return m.replace('.','/')+'.lean'
seen=set(); stack=[i for i in imports if i.startswith('AlgebraicJacobian')]
while stack:
    m=stack.pop()
    if m in seen: continue
    seen.add(m)
    p=mod2path(m)
    if os.path.exists(p):
        for i in re.findall(r'^import\s+(AlgebraicJacobian\S*)',open(p).read(),re.M):
            if i not in seen: stack.append(i)
disk=[]
for dp,dn,fn in os.walk('AlgebraicJacobian'):
    for f in fn:
        if f.endswith('.lean'): disk.append(os.path.join(dp,f).replace('/','.')[:-5])
print('on disk',len(disk),'rooted',len(seen))
un=[d for d in disk if d not in seen]
print('UNROOTED:', un)
"

